// HasApplicationSessions applies the HasEdge predicate on the "application_sessions" edge.
func HasApplicationSessions() predicate.AdApplication {
	return predicate.AdApplication(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ApplicationSessionsTable, ApplicationSessionsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasApplicationSessionsWith applies the HasEdge predicate on the "application_sessions" edge with a given conditions (other predicates).
func HasApplicationSessionsWith(preds ...predicate.ApplicationSession) predicate.AdApplication {
	return predicate.AdApplication(func(s *sql.Selector) {
		step := newApplicationSessionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

