// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AdApplication) predicate.AdApplication {
	return predicate.AdApplication(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AdApplication) predicate.AdApplication {
	return predicate.AdApplication(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AdApplication) predicate.AdApplication {
	return predicate.AdApplication(sql.NotPredicates(p))
}
